export type SavedRecipe = {
    /**
     * False when this exact immutable revision was already present.
     */
    created: boolean;
    recipe: CurationRecipe;
};

/**
 * The result of saving a drawing.
 */
export type SavedRevision = {
    /**
     * False when this exact set of shapes was already stored.
     */
    created: boolean;
    head: ImageHead;
    revision: AnnotationRevision;
};

export type SavedWorkflow = {
    definition: WorkflowSpec;
    registered_at: string;
    registered_by: string;
    revision: DefinitionRevision;
};

/**
 * A definition's schedule, as somebody set it.
 *
 * **Mutable, and deliberately not part of the definition's content address.**
 * Changing the hour must not mint a new pipeline revision: that would be a
 * revision history about scheduling, which is the same mistake as making
 * `produced_by` part of a dataset version's identity. It lives as a head
 * beside the definition, the way a prompt's labels live beside its versions.
 */
export type Schedule = {
    /**
     * A field rather than a flattened one, and not for taste: serde's
     * `deny_unknown_fields` and `flatten` do not compose, and the bodies here
     * deny unknown fields so a `cron` somebody hoped would work is named
     * rather than ignored. Nesting is what keeps that guardrail.
     */
    cadence: Cadence;
    /**
     * Off keeps the schedule and starts nothing. Deleting it and re-typing it
     * next month is how a schedule gets re-typed wrongly.
     */
    enabled?: boolean;
    overlap?: OverlapPolicy;
    /**
     * An IANA name — `Europe/Warsaw`, not an offset.
     *
     * An offset is unambiguous and wrong twice a year: somebody who asked for
     * nine in the morning means nine in the morning in March and in October.
     * Storing the zone is what lets the answer change when the zone's rules
     * say it should.
     */
    timezone: string;
};

/**
 * A deferred append, as a caller asks for one.
 */
export type ScheduleTimerBody = {
    due_at: string;
    /**
     * What to append when it comes due. Composed by the caller, because an
     * engine that assembled one would be deciding what a timeout means.
     */
    message: HostedMessage;
    /**
     * The worker's own id, unique inside this execution.
     */
    timer_id: string;
};

/**
 * A schedule, when it next fires, and what setting it started.
 */
export type ScheduleView = {
    /**
     * What the tick did, newest first.
     *
     * Read from the **workflow store**, not from the schedule object. They
     * used to be one thing, which is what let a tick's write-back undo an
     * edit or resurrect a deleted schedule; configuration and slot
     * outcomes now have different writers and live in different places.
     *
     * Empty when this deployment wired no execution store — there is then no
     * tick either, so nothing has fired and an empty list is the true answer
     * rather than a missing one.
     */
    firings?: Array<SlotRecord>;
    /**
     * When the tick would next start it. `None` while it is off.
     *
     * Answered here rather than left to the caller, and that is the same rule
     * as `RunView::allowed`: the panel computing it would be a second
     * implementation of `slots_between` — in another language, with its own
     * idea of when the clocks change — free to show an hour the run does not
     * happen at.
     */
    next_run?: string | null;
    schedule: ScheduledDefinition;
    /**
     * The run `run_now` started, when it was asked for.
     */
    started?: string | null;
};

/**
 * A definition's schedule, as stored.
 */
export type ScheduledDefinition = {
    definition_kind: DefinitionKind;
    definition_name: string;
    /**
     * When the *current cadence* began to apply.
     *
     * Without it every schedule is handed the whole interval a checkpoint has
     * accumulated, so one written while the worker was down for
     * three days ran three days of slots the moment it came back — and
     * changing an hour during an outage re-ran the past under the new rule.
     *
     * Not `updated_at`, and that is the review's own warning: an edit that
     * does not change *when* it fires would then quietly drop a slot that was
     * already due. It moves only when [`Schedule::fires_the_same_as`] says the
     * rule changed — which makes re-enabling an activation too, so a schedule
     * switched back on starts from now rather than running the days it was
     * off.
     *
     * Optional so a schedule stored before this field existed still reads;
     * [`Self::effective_from`] answers for it, and the fallback is
     * `updated_at` because that is when such a schedule was last written.
     */
    effective_from?: string | null;
    schedule: Schedule;
    /**
     * Who set it, from the session. Recorded because a run nobody remembers
     * asking for at three in the morning is a question with an answer.
     */
    set_by?: string;
    updated_at: string;
};

/**
 * One metric, on the baseline and on the candidate.
 */
export type Score = {
    baseline?: number | null;
    candidate?: number | null;
    metric: string;
};

/**
 * Which SDK produced an event.
 *
 * Serialised as a plain string with an unknown value passing through: an SDK
 * this backend has never heard of must still be able to publish.
 */
export type Sdk = 'Python' | 'Typescript' | 'Rust' | {
    Other: string;
};

/**
 * What a caller sets.
 *
 * `deny_unknown_fields`, like every other command body here: a `cron` somebody
 * hoped would work is a 400 naming it rather than a field that is ignored and
 * reads as accepted.
 */
export type SetScheduleBody = {
    cadence: Cadence;
    enabled?: boolean;
    overlap?: OverlapPolicy;
    /**
     * What makes two `run_now` requests the same request.
     *
     * The execution id is derived from it, so a retry — a proxy repeating the
     * PUT, a click on a button whose first response was slow — lands on the
     * run it already started instead of beside it. Without it the id comes
     * from the second the request arrived in, which made a retry one second
     * later a second run.
     *
     * Any stable string the caller minds: the panel sends one per user
     * action.
     */
    request_id?: string | null;
    /**
     * Start it once, now, as well as saving it.
     */
    run_now?: boolean;
    /**
     * An IANA name — `Europe/Warsaw`. Never an offset; see [`Schedule`].
     */
    timezone: string;
};

/**
 * What the decider did with a report.
 */
export type Settled = {
    attempt: number;
    outcome: Settlement;
    step_id: string;
    /**
     * Whether the attempt finished its work successfully.
     *
     * Kept beside [`Self::outcome`], which subsumes it, because an SDK rolls
     * separately from this server and every released one reads this field —
     * removing it in the release that adds the wider answer would break a
     * worker whose only fault was being the version it was pinned at. The same
     * staged-removal discipline the schema keeps. `outcome` is the one a new
     * client asks; this is derived from it and never set independently.
     *
     * Marked deprecated in the contract rather than only in prose, so the
     * removal is something every generated client can see coming instead of
     * something somebody has to remember. It goes when no worker still reads
     * it.
     *
     * @deprecated
     */
    succeeded: boolean;
};

/**
 * Which of the three things a report turned out to be.
 *
 * Named rather than inferred from [`Settled::succeeded`], which answers a
 * narrower question and answers it `false` for a failure and a park alike. A
 * client that checked only the boolean would agree with the server about a
 * park by coincidence rather than by name.
 */
export const Settlement = {
    COMPLETED: 'completed',
    FAILED: 'failed',
    PARKED: 'parked'
} as const;

/**
 * Which of the three things a report turned out to be.
 *
 * Named rather than inferred from [`Settled::succeeded`], which answers a
 * narrower question and answers it `false` for a failure and a park alike. A
 * client that checked only the boolean would agree with the server about a
 * park by coincidence rather than by name.
 */
export type Settlement = typeof Settlement[keyof typeof Settlement];

/**
 * One written shard of a staged artifact.
 *
 * The unit of resume and the unit of proof. `digest` is over the shard's
 * plaintext bytes — before any encryption, so an archive that seals its
 * shards and an importer that does not produce comparable references — and it
 * is what [`version_of`] builds the artifact's identity from.
 */
export type ShardRef = {
    /**
     * `sha256` of the shard's plaintext JSONL. What proves a shard was not
     * swapped for another.
     */
    digest: string;
    index: number;
    rows: number;
};

/**
 * The slot a definition is due for, as a key.
 *
 * The slot is the *intended* instant and never the moment the tick noticed
 * it: a run started late after an outage belongs to the nine o'clock it was
 * for, which is also what makes the derived execution id stable across a
 * replay.
 */
export type SlotKey = {
    definition_kind: DefinitionKind;
    definition_name: string;
    slot: string;
};

/**
 * What the tick decided about one slot. Terminal: a settled slot is done.
 *
 * **The scheduler's own decision, and never the run's outcome.** Whether the
 * run then succeeded is on the event log, which the Workflows view folds, and
 * a second copy here would be free to disagree with it (ADR_0026).
 *
 * The three the previous release's `FiringOutcome` had, unchanged, because
 * the panel already renders them and they are already what a person reads.
 */
export const SlotOutcome = {
    STARTED: 'started',
    SKIPPED: 'skipped',
    REFUSED: 'refused'
} as const;

/**
 * What the tick decided about one slot. Terminal: a settled slot is done.
 *
 * **The scheduler's own decision, and never the run's outcome.** Whether the
 * run then succeeded is on the event log, which the Workflows view folds, and
 * a second copy here would be free to disagree with it (ADR_0026).
 *
 * The three the previous release's `FiringOutcome` had, unchanged, because
 * the panel already renders them and they are already what a person reads.
 */
export type SlotOutcome = typeof SlotOutcome[keyof typeof SlotOutcome];

/**
 * A slot as the store holds it.
 *
 * Flat rather than an outcome carrying its own fields, and that is not
 * laziness: it is one row in `schedule_slots` and one shape the panel already
 * renders, so a column, a field and a rendered line are the same three things
 * end to end.
 */
export type SlotRecord = SlotKey & {
    /**
     * Why it was refused — or, while it is unsettled, what the last attempt
     * ran into. A slot that has been failing every tick says what is wrong
     * with it rather than looking untouched.
     */
    detail?: string | null;
    /**
     * The run this slot started, or the one that blocked it.
     */
    execution_id?: string | null;
    /**
     * Who is trying, and since when. Absent once it is settled.
     */
    lease_owner?: string | null;
    leased_at?: string | null;
    outcome?: null | SlotOutcome;
    updated_at: string;
};

/**
 * Who sent the event. Enough to find the process that produced a bad batch.
 */
export type Source = {
    instance?: string | null;
    sdk: Sdk;
    service: string;
};

/**
 * How the bytes are obtained.
 */
export const SourceAccess = {
    OPEN: 'open',
    REQUEST: 'request',
    ACADEMIC: 'academic'
} as const;

/**
 * How the bytes are obtained.
 */
export type SourceAccess = typeof SourceAccess[keyof typeof SourceAccess];

/**
 * A loaded catalogue: the corpora somebody checked, and where to look for more.
 *
 * Cloneable and cheap to hold. An instance loads one at start-up and every
 * reader shares it — the alternative, re-reading a file per request, would
 * make the answer depend on when it was asked.
 */
export type SourceCatalog = {
    directories?: Array<SourceDirectory>;
    sources?: Array<DatasetSource>;
};

/**
 * A place to go looking, rather than a corpus.
 */
export type SourceDirectory = {
    name: string;
    notes?: string;
    url: string;
};

/**
 * One file a batch was read out of, as the hub described it.
 */
export type SourceFile = {
    /**
     * Whatever the hub published: an LFS `sha256`, a git blob id, an ETag.
     * Never verified here, because these bytes are not the bytes this
     * registry stores — an image is hashed on arrival and *that* digest is
     * its identity.
     */
    digest?: string;
    name: string;
    size_bytes?: number | null;
};

export type SourcePage = {
    directories: Array<SourceDirectory>;
    sources: Array<DatasetSource>;
    /**
     * Rows before the filter, so a caller can tell an empty filter from an
     * empty table.
     */
    total: number;
};

/**
 * What the licence permits, stated conservatively.
 */
export const SourceUsage = {
    COMMERCIAL: 'commercial',
    NON_COMMERCIAL: 'non_commercial',
    UNCLEAR: 'unclear'
} as const;

/**
 * What the licence permits, stated conservatively.
 */
export type SourceUsage = typeof SourceUsage[keyof typeof SourceUsage];

/**
 * Lowercase hex span id
 */
export type SpanId = string;

export const SpanKind = {
    INTERNAL: 'internal',
    SERVER: 'server',
    CLIENT: 'client',
    PRODUCER: 'producer',
    CONSUMER: 'consumer'
} as const;

export type SpanKind = typeof SpanKind[keyof typeof SpanKind];

export const SpanOutcome = { OK: 'ok', ERROR: 'error' } as const;

export type SpanOutcome = typeof SpanOutcome[keyof typeof SpanOutcome];

export type SpanPage = {
    next_cursor?: string | null;
    spans: Array<SpanRow>;
    /**
     * Spans matching the filter, before the page limit.
     */
    total_known: number;
};

/**
 * One span, flattened for a list rather than for a tree.
 */
export type SpanRow = {
    agent_id?: string | null;
    duration_ms: number;
    end: string;
    kind: SpanKind;
    model?: string | null;
    name: string;
    /**
     * The four attributes worth filtering on, lifted out of `attributes` so
     * the panel does not have to walk the list to render a row.
     */
    operation?: string | null;
    parent_span_id?: null | SpanId;
    /**
     * From the map key: a `CompletedSpan` carries no run id of its own.
     */
    run_id: string;
    span_id: SpanId;
    start: string;
    status: SpanStatus;
    step_type?: string | null;
    tool?: string | null;
    trace_id: TraceId;
};

export type SpanStatus = {
    status: 'unset';
} | {
    status: 'ok';
} | {
    message: string;
    status: 'error';
};

/**
 * Which side of the split a family is on.
 */
export const Split = {
    TRAIN: 'train',
    VALIDATION: 'validation',
    TEST: 'test'
} as const;

/**
 * Which side of the split a family is on.
 */
export type Split = typeof Split[keyof typeof Split];

/**
 * How families are dealt out. Percentages, summing to 100.
 */
export type SplitRatios = {
    test: number;
    train: number;
    validation: number;
};

/**
 * What a batch is for, decided once and pinned.
 *
 * Rights, evidence and source sit here rather than on each page because they
 * are properties of the *corpus*: a per-page field would invite a pipeline to
 * derive them from a column, which is the mirror's word laundered through a
 * `withEntry`. This is also the "pinned source" half of "re-running the same
 * pinned source and pipeline yields the same version".
 */
export type StageBatchRequest = {
    description?: string;
    /**
     * Who checked that, where and when. Recorded, never enforced.
     */
    evidence?: RightsEvidence;
    project: string;
    /**
     * What the caller asserts may be done with every image in this batch.
     */
    rights?: UsageRights;
    source?: ImportSource;
};

/**
 * A batch as it sits in the store.
 */
export type StagedBatch = {
    batch_id: string;
    created_at: string;
    created_by?: string;
    description: string;
    /**
     * `sha256(request ‖ every page digest, in order)`, once sealed.
     */
    digest?: string | null;
    evidence: RightsEvidence;
    /**
     * One entry per stored page, in order. The same [`ShardRef`] the
     * conversation export writes, because it is the same thing: an ordered,
     * digested piece of a staged artifact.
     */
    pages: Array<ShardRef>;
    project: string;
    /**
     * What was asked for, hashed. Half of the batch's content address.
     */
    request_digest: string;
    rights: UsageRights;
    rows: number;
    /**
     * True once the batch takes no more rows. Set by queueing a job.
     */
    sealed: boolean;
    /**
     * Pages on which no two rows shared a `group_id`.
     *
     * The family split is the one mistake an import cannot detect afterwards:
     * a `group_id` mapped from the file name gives every image its own
     * family, the test score then measures memorisation, and nothing in the
     * numbers says so. Counted per page rather than over the whole batch
     * because the alternative is a set of every group id a million-row import
     * has seen, held in a manifest — so what this supports is the exact
     * statement "every page of this batch gave each row its own family",
     * which is what a filename mapping produces and what a real one does not.
     */
    singleton_pages: number;
    source: ImportSource;
    updated_at: string;
};

/**
 * What a caller may ask this system to run.
 *
 * Note what is not here, which is the same absence as `LaunchBody`'s and
 * `RerunBody`'s: no endpoint, no script, no host. A plan names a binding and
 * its parameters, and every executor's address is configuration.
 * `deny_unknown_fields` so an attempt to supply one — or a `backend`, a `mode`
 * or a `publish` flag that is not implemented — is a 400 naming it rather than
 * a field silently ignored that reads as accepted.
 */
export type StartExecutionBody = {
    /**
     * Where that window ends, in seconds since the epoch. `None` is now.
     *
     * Two runs that pin the same span compile to one `plan_id` and one cache
     * key, which is what makes a scheduled build of a fixed period cheap the
     * second time. Left out, every run pins a fresh span — which is right for
     * "curate the last hour" and is why a hit is something a caller asks for
     * rather than something they get by accident.
     */
    as_of?: number | null;
    /**
     * Who decides what runs next. Left out, this system does — which is what
     * every curation pipeline and every scheduled run wants, and what this
     * route did before the field existed.
     */
    decided_by?: Decider;
    /**
     * Values bound when the execution was requested, available to every step.
     */
    parameters?: {
        [key: string]: unknown;
    };
    payloads?: null | PayloadPolicy;
    target: ExecutionTarget;
    /**
     * How wide the source's time window is, in seconds.
     *
     * Resolved to exact bounds **here**, once, rather than at dispatch: the
     * plan then records what it was asked for, a retry reads the same rows,
     * and a cache key can exist at all.
     */
    window_seconds?: number | null;
};

/**
 * What opens a run.
 */
export type StartRunRequest = {
    code?: string;
    /**
     * `project@export-sha256`, ideally.
     */
    dataset: string;
    device?: string;
    framework?: string;
    model: string;
    params?: {
        [key: string]: unknown;
    };
    run_id: string;
    schema_version?: string | null;
    workflow_run_id?: string | null;
};

/**
 * What drives orchestration. Nine, and no more without a reason written down.
 */
export const StateType = {
    SCHEDULED: 'scheduled',
    PENDING: 'pending',
    RUNNING: 'running',
    AWAITING_INPUT: 'awaiting_input',
    COMPLETED: 'completed',
    FAILED: 'failed',
    CRASHED: 'crashed',
    CANCELLED: 'cancelled',
    PAUSED: 'paused'
} as const;

/**
 * What drives orchestration. Nine, and no more without a reason written down.
 */
export type StateType = typeof StateType[keyof typeof StateType];

/**
 * One plan step, and the blocks somebody drew that became it.
 */
export type StepBlocks = {
    /**
     * The authored block ids, in order. Empty for a step no canvas block
     * compiled to, where the step id is the address.
     */
    blocks: Array<string>;
    runtime: RuntimeKind;
    step_id: string;
};

/**
 * Retrieval, embedding, rerank, guardrail — grouped by kind, then by name.
 *
 * Retrieval latency is the number a slow RAG turn gets debugged against, and
 * it is invisible in the LLM and tool breakdowns.
 */
export type StepBreakdown = {
    calls: number;
    failures: number;
    latency: Percentiles;
    name: string;
    step_type: string;
};

export type StepError = {
    class: FailureClass;
    message: string;
};

/**
 * The logical state of one plan step, across every attempt it took.
 */
export type StepState = {
    /**
     * Every answer this step has been given, oldest first.
     *
     * What a resumed attempt reads. See [`InputAnswer`] for why it is a list
     * and why it lives on the step rather than on the attempt that asked.
     */
    answers?: Array<InputAnswer>;
    attempts?: Array<AttemptRecord>;
    awaiting?: null | InputRequest;
    cache_key?: string | null;
    /**
     * The attempt number in flight, or the last one taken. `0` before any.
     */
    current_attempt: number;
    outputs?: Array<ArtifactRef>;
    runtime: RuntimeKind;
    state: RunState;
    step_id: string;
};

/**
 * A stored image blob and what it is.
 */
export type StoredBlob = {
    bytes: number;
    content_type: string;
    /**
     * False when these exact bytes were already stored.
     */
    created: boolean;
    /**
     * SHA-256 of the bytes, computed here. This is the `image_id`.
     */
    image_id: string;
    /**
     * What to put in `ImageRecord::uri`. See [`BLOB_SCHEME`].
     */
    uri: string;
};

/**
 * Where the stream got to, and whether this call is what put it there.
 */
export type StreamAppended = {
    /**
     * `false` when this batch had already been appended — a redelivery, not a
     * race. The worker carries on from `version` either way.
     */
    created: boolean;
    /**
     * The version to send as the next `expected_version`.
     */
    version: number;
};

/**
 * The stream a run's events live on.
 *
 * One stream per **run**, not per conversation: a conversation can fan out
 * into several agent runs at once, and partitioning the log by conversation
 * would serialise runs that have no reason to wait for each other.
 */
export type StreamName = {
    stream_id: string;
    stream_type: string;
};

export type SuitePage = {
    suites: Array<SuiteSummary>;
    total: number;
};

/**
 * A suite on a dataset, across every evaluation of it that is retained.
 *
 * The level above a report, and the one MLflow calls an experiment.
 */
export type SuiteSummary = {
    dataset?: string | null;
    evaluations: number;
    failed: number;
    last_evaluation_id: string;
    last_started_at: string;
    last_status: EvaluationStatus;
    /**
     * The newest finished evaluation's metrics, and the change from the one
     * before it. A number with no direction is the thing an evaluation page
     * is usually accused of being.
     */
    latest_metrics: {
        [key: string]: number;
    };
    metric_deltas: {
        [key: string]: number;
    };
    pass_rate?: number | null;
    running: number;
    succeeded: number;
    suite: string;
};

/**
 * What kind of definition is being run.
 *
 * Two arms, which is what the enum was for: both compile to the same
 * `ExecutionPlan` from different editors, with different provenance, and the
 * names live in different registries under different prefixes. A
 * `kind` nobody had to send would have to be guessed from the name — and two
 * definitions may share one, which is exactly what `WorkflowSpec` being saved
 * beside `CurationPipeline` allows.
 */
export const TargetKind = { CURATION_PIPELINE: 'curation_pipeline', WORKFLOW: 'workflow' } as const;

/**
 * What kind of definition is being run.
 *
 * Two arms, which is what the enum was for: both compile to the same
 * `ExecutionPlan` from different editors, with different provenance, and the
 * names live in different registries under different prefixes. A
 * `kind` nobody had to send would have to be guessed from the name — and two
 * definitions may share one, which is exactly what `WorkflowSpec` being saved
 * beside `CurationPipeline` allows.
 */
export type TargetKind = typeof TargetKind[keyof typeof TargetKind];

/**
 * A number a request has to look like.
 *
 * The shape is a list rather than a string so a server can check it; `None`
 * in a dimension is "any", which is how a batch axis is written. A runtime
 * that validates against this refuses a wrong request instead of reshaping it
 * into something that predicts confidently and wrongly.
 */
export type TensorSpec = {
    /**
     * For a classifier: what index 0, 1, 2 … mean.
     *
     * On the package rather than in the serving code, because a label order
     * that lives in a deployment is a label order that silently permutes when
     * somebody retrains — every metric stays finite and nothing says so. The
     * same failure `ExportDataset` checks `schema_version` for.
     */
    classes?: Array<string>;
    description?: string;
    /**
     * `float32`, `int64`, `uint8`. Free text, because the vocabulary is the
     * runtime's and an enum here would be one framework's list imposed on
     * every other.
     */
    dtype?: string;
    name: string;
    /**
     * `[null, 3, 224, 224]`. A `null` is a free dimension.
     */
    shape?: Array<number | null>;
};

/**
 * A message a hosted decider asked this engine to append later.
 *
 * The one *active* thing this engine does for a hosted run, and it is
 * deliberately the smallest possible active thing: a deferred append.
 * The worker composes the message when it schedules the timer, and the engine
 * stores it and hands it back at the time — so "the engine does not interpret
 * the messages" survives intact. It is not reading a stream to work out that
 * something is due; it was told, explicitly, in a row.
 *
 * ## Why a row rather than the stream
 *
 * `agentic.workflow.Saga` already keeps its timers *in* the stream, as
 * `saga.timeout_scheduled` events, and works out what is due by folding it.
 * That fold is the worker's and stays the worker's. What it cannot do from
 * there is *notice*: nothing wakes up and looks. A row is what an index over
 * every hosted run can be built on, so one tick finds what is due across all
 * of them without reading a single stream.
 */
export type Timer = {
    due_at: string;
    execution: ExecutionId;
    /**
     * What to append when it comes due. Composed by the worker at the moment
     * it schedules, never assembled here — an engine that built this would be
     * deciding what a timeout means.
     */
    message: HostedMessage;
    /**
     * The worker's own id, unique inside one execution. `agentic`'s
     * `timeout_id`, and the reason a repeated schedule is one timer.
     */
    timer_id: string;
};

/**
 * One thing to do to this execution's timers.
 *
 * A tagged pair rather than a struct with a `cancel` flag, because the two
 * carry different fields and a body that could name a `due_at` while
 * cancelling would be a shape with a meaningless half.
 */
export type TimerBody = {
    /**
     * Hold this message until `due_at`. Scheduling one id twice is one timer,
     * which is what makes a decider's retry safe.
     */
    schedule: ScheduleTimerBody;
} | {
    /**
     * Withdraw it. A no-op when there is none, because a saga that cancels a
     * timeout it already handled is doing the ordinary thing.
     */
    cancel: CancelTimerBody;
};

export type ToolBreakdown = {
    calls: number;
    failures: number;
    latency: Percentiles;
    tool_name: string;
};

/**
 * What a tool handed back.
 *
 * Attached to the turn rather than folded into a `Text` part, because a
 * failure is a training signal and a stringified error is not: an SFT shape
 * wants the successful ones, a preference shape often wants exactly the pairs
 * where one branch failed.
 */
export type ToolResult = {
    call_id: string;
    content: string;
    error?: string;
    name: string;
    ok: boolean;
};

export type Totals = {
    /**
     * Cached as a share of input. The one number that says whether prompt
     * caching is doing anything.
     */
    cache_hit_ratio: number;
    cached_tokens: number;
    failed: number;
    input_tokens: number;
    llm_calls: number;
    output_tokens: number;
    running: number;
    runs: number;
    /**
     * Retrievals, embeddings, reranks, guardrails — everything traced as a
     * step rather than as an LLM or tool call.
     */
    step_calls: number;
    succeeded: number;
    tool_calls: number;
};

/**
 * Lowercase hex trace id
 */
export type TraceId = string;

/**
 * One training run, with everything it accumulated.
 */
export type TrainingRun = {
    best?: null | BestMetric;
    checkpoints?: Array<CheckpointRecord>;
    /**
     * The code that ran. A git revision, usually.
     */
    code?: string;
    /**
     * `project@export-sha256` from the annotation registry. A bare project
     * name is recorded and marks the run irreproducible rather than being
     * refused: a smoke test on an unversioned dataset is a legitimate thing
     * to do, and refusing it would only teach people to lie about it.
     */
    dataset: string;
    device?: string;
    ended_at?: string | null;
    epochs?: Array<EpochRecord>;
    error?: string | null;
    framework?: string;
    /**
     * When this run last wrote anything. The only honest answer to "is it
     * still alive", and the field a reader draws a stall from.
     */
    last_heard_from: string;
    /**
     * The model being trained — a name, not a version. The version is what
     * this run *produces*; see [`crate::model::ModelVersion`].
     */
    model: string;
    params?: {
        [key: string]: unknown;
    };
    profiles?: Array<ProfileRecord>;
    /**
     * Whether this run can be pointed at afterwards and repeated. Decided
     * once, when the run opens, and stored rather than re-derived: a rule
     * computed in three places is a rule three places can disagree about, and
     * the panel is one of them.
     */
    reproducible?: boolean;
    run_id: string;
    /**
     * How many times the sampled series has been halved. The effective
     * interval is the original one times two to this power, and saying so is
     * what stops somebody reading a decimated curve as a complete one.
     */
    sample_decimations?: number;
    samples?: Array<SampleRecord>;
    schema_version?: string | null;
    started_at: string;
    status: TrainingStatus;
    /**
     * Set when the orchestrator launched this run, so it joins the workflow
     * execution it belongs to. See ADR_0012 and ADR_0016.
     */
    workflow_run_id?: string | null;
};

export type TrainingRunPage = {
    runs: Array<TrainingRunSummary>;
    total: number;
};

/**
 * A run as it appears in a list: everything but the curve.
 */
export type TrainingRunSummary = {
    best?: null | BestMetric;
    checkpoints: number;
    dataset: string;
    device?: string;
    duration_ms?: number | null;
    ended_at?: string | null;
    epochs: number;
    error?: string | null;
    framework?: string;
    last_heard_from: string;
    model: string;
    reproducible: boolean;
    run_id: string;
    started_at: string;
    status: TrainingStatus;
    workflow_run_id?: string | null;
};

/**
 * What the consent covers.
 *
 * Separate scopes rather than one "may train" flag, because they are
 * genuinely different permissions and the difference is where the accidents
 * happen: an evaluation set that quietly becomes a training set is the same
 * mistake as a research-licensed corpus in a commercial model, one field over.
 */
export const TrainingScope = {
    TRAIN: 'train',
    EVALUATE: 'evaluate',
    SHARE: 'share'
} as const;

/**
 * What the consent covers.
 *
 * Separate scopes rather than one "may train" flag, because they are
 * genuinely different permissions and the difference is where the accidents
 * happen: an evaluation set that quietly becomes a training set is the same
 * mistake as a research-licensed corpus in a commercial model, one field over.
 */
export type TrainingScope = typeof TrainingScope[keyof typeof TrainingScope];

/**
 * Where a run is.
 *
 * `Running` is the *absence* of an end, not a claim that anything is
 * happening — exactly the rule the projector follows for agent runs. A
 * trainer killed by an OOM and a trainer thinking for twenty minutes look
 * identical from here, so nothing in this crate decides which one it is.
 * [`TrainingRun::last_heard_from`] is what a reader draws the line from.
 */
export const TrainingStatus = {
    RUNNING: 'running',
    SUCCEEDED: 'succeeded',
    FAILED: 'failed',
    CANCELLED: 'cancelled'
} as const;

/**
 * Where a run is.
 *
 * `Running` is the *absence* of an end, not a claim that anything is
 * happening — exactly the rule the projector follows for agent runs. A
 * trainer killed by an OOM and a trainer thinking for twenty minutes look
 * identical from here, so nothing in this crate decides which one it is.
 * [`TrainingRun::last_heard_from`] is what a reader draws the line from.
 */
export type TrainingStatus = typeof TrainingStatus[keyof typeof TrainingStatus];

/**
 * The half that is encrypted.
 *
 * A type of its own rather than two fields on the head, because the split is
 * the security boundary: everything in here is sealed, everything outside it
 * is readable by anyone who may list the archive, and a field that moved
 * across the line by accident would be a leak nobody could see in a diff.
 */
export type TurnContent = {
    parts?: Array<ContentPart>;
    tool_results?: Array<ToolResult>;
};

export type TurnPage = {
    /**
     * Where to resume. Absent at the end of the conversation.
     */
    next_offset?: number | null;
    total: number;
    turns: Array<ArchivedTurn>;
};

/**
 * Who decided, when, and why.
 */
export type TurnReview = {
    decided_at?: string | null;
    note?: string;
    preference?: null | PreferenceLabel;
    reviewer?: string;
    state?: TurnReviewState;
};

/**
 * One reviewer's decision about one turn.
 */
export type TurnReviewRequest = {
    /**
     * What the reviewer saw that the scanner did not — an unsafe answer, a
     * name the rules do not recognise. Appended to the turn's findings rather
     * than replacing them: a scanner finding a human disagreed with is a fact
     * about both of them.
     */
    findings?: Array<HumanFinding>;
    note?: string;
    preference?: null | PreferenceLabel;
    state: TurnReviewState;
};

/**
 * Whether a human has decided about this turn.
 */
export const TurnReviewState = {
    PENDING: 'pending',
    APPROVED: 'approved',
    REJECTED: 'rejected'
} as const;

/**
 * Whether a human has decided about this turn.
 */
export type TurnReviewState = typeof TurnReviewState[keyof typeof TurnReviewState];

/**
 * Whether the content is still there.
 */
export const TurnState = { HELD: 'held', ERASED: 'erased' } as const;

/**
 * Whether the content is still there.
 */
export type TurnState = typeof TurnState[keyof typeof TurnState];

/**
 * What may be done with an image, and therefore with a model trained on it.
 */
export type UsageRights = {
    grant?: string;
    kind: 'owned';
} | {
    kind: 'licensed';
    license: string;
    url?: string | null;
} | {
    kind: 'research_only';
    license: string;
    url?: string | null;
} | {
    kind: 'unknown';
};

/**
 * All references are resolved before this snapshot is prepared. Configuration
 * and code are digested artifacts, so changing them cannot retarget a variant.
 */
export type VariantManifest = {
    code: ArtifactRef;
    dataset: DatasetReference;
    experiment_id: string;
    generation_config: ArtifactRef;
    model?: null | VersionReference;
    prompt?: null | VersionReference;
    response_schema?: null | ArtifactRef;
    schema_version: number;
    tools?: null | ArtifactRef;
    workflow?: null | VersionReference;
};

/**
 * Where a version came from.
 *
 * The distinction the panel needs to answer "did a person write this, or did
 * an optimiser?" — which is the first question asked about a prompt that is
 * behaving strangely.
 */
export type VersionOrigin = {
    origin: 'authored';
} | {
    algorithm: string;
    optimization_id: string;
    origin: 'optimized';
};

/**
 * `version` is the owner's immutable revision, never a deployment label.
 * External revisions must be resolved by the producer; validation of this
 * contract is not evidence that the referenced resource exists.
 */
export type VersionReference = {
    name: string;
    version: string;
};

/**
 * Why a corpus was withdrawn, and when.
 *
 * An export is immutable and a withdrawal does not change that: the manifest
 * keeps every count, digest and exclusion it had. What is gone is the rows,
 * because the alternative is a published corpus holding words somebody asked
 * to have deleted — and an erasure that stopped at the archive would be an
 * erasure in name only.
 */
export type Withdrawal = {
    at: string;
    by?: string;
    /**
     * The conversations whose erasure caused this.
     */
    conversations: Array<string>;
};

/**
 * One attempt, and everything performing it needs.
 */
export type WorkAssignment = {
    /**
     * Every answer this step has already been given, oldest first.
     *
     * Empty for almost every assignment. It is not empty when this attempt
     * exists *because* somebody answered the question the previous one stopped
     * to ask: the work re-runs from the beginning, so it reaches that question
     * again and reads the answer instead of parking a second time.
     *
     * Consumed in order, which is the order a replay asks them in.
     */
    answers: Array<InputAnswer>;
    attempt: number;
    /**
     * `<execution>/<step>/<attempt>` — what the work is idempotent by, and
     * what a task with a side effect keys it on.
     */
    context_id: string;
    execution_id: string;
    /**
     * What the parents produced, by name. The bytes are read one at a time
     * through this attempt's own `inputs/{name}` route.
     */
    inputs: Array<ArtifactRef>;
    /**
     * Whether somebody else held this attempt first.
     *
     * The reactor asks its runtime by idempotency key before re-running a
     * takeover, because a timeout proves nothing about whether the previous
     * call finished. A worker has no such lookup to offer, so it is told
     * instead: a task with a side effect must be idempotent by `context_id`,
     * and this is when that matters.
     */
    is_retake: boolean;
    /**
     * When this claim stops being trusted unless it is renewed.
     *
     * An instant rather than a duration, and the difference matters: a worker
     * told "five minutes" has to agree with this process about when the five
     * minutes started, and the two clocks are the whole question. A deadline
     * is one fact. It also means a client cannot hard-code the lease length
     * and keep beating at the wrong rate the day the rule moves —
     * `aiwatcher_jobs` owns that number, and nothing here restates it.
     */
    lease_expires_at: string;
    /**
     * Named row outputs required by the pinned plan.
     */
    outputs: Array<string>;
    /**
     * What the run itself was started with.
     */
    parameters: {
        [key: string]: unknown;
    };
    /**
     * The step's authored parameters.
     */
    params: {
        [key: string]: unknown;
    };
    parent_span_id: string;
    queue: string;
    /**
     * The result route can acknowledge a matching outcome from durable history.
     */
    report_idempotent: boolean;
    step_id: string;
    /**
     * `name@version`, from the plan. The worker matches it against what it
     * registered; the server already did, which is why this is a fact rather
     * than a request.
     */
    task_ref: string;
    /**
     * The step's own deadline. Past it the server stops waiting for a report.
     */
    timeout_seconds: number;
    trace_id: string;
    /**
     * Correlation supplied by the platform; the worker emits only child spans.
     */
    workflow_id: string;
};

/**
 * What a worker did with its attempt.
 */
export type WorkReport = {
    /**
     * Whether this may answer for its cache key later. The worker
     * answers it because only the process that ran the work knows what it
     * managed to do.
     */
    cacheable?: boolean;
    diagnostics?: string | null;
    outcome: 'completed';
    /**
     * References this attempt's own `outputs/{name}` route handed back.
     */
    outputs?: Array<ArtifactRef>;
    /**
     * A bounded control value. Rows go in an artifact — a result that
     * grows with the data is one that eventually cannot be replayed.
     */
    result?: unknown;
} | {
    /**
     * Whether trying again could plausibly produce a different answer.
     * The worker classifies it, because the process that made the call is
     * the one that knows.
     */
    class: FailureClass;
    diagnostics?: string | null;
    message: string;
    outcome: 'failed';
} | {
    /**
     * Answers are buttons. Empty means free-form.
     */
    choices?: Array<string>;
    diagnostics?: string | null;
    /**
     * What happens if nobody answers in time. Refused without a deadline,
     * because a policy with no clock behind it is a rule nothing fires.
     */
    on_timeout?: OnTimeout;
    outcome: 'parked';
    /**
     * What is being asked, in the words the person reads.
     */
    prompt: string;
    /**
     * The role that may answer. A gate only ever raises the editor floor
     * the answer route already holds.
     */
    role?: string;
    /**
     * How long the run waits before `on_timeout` decides for it. `None`
     * waits as long as it takes, which is the default.
     */
    timeout_seconds?: number | null;
};

/**
 * A worker saying which attempt it is talking about.
 */
export type WorkerBody = {
    worker: string;
};

/**
 * A report, with the worker that is making it.
 *
 * Two structs rather than a flattened one: serde's `flatten` and
 * `deny_unknown_fields` do not compose, and the report is a tagged enum whose
 * variants are the whole point of the body being checked.
 */
export type WorkerReport = WorkReport & {
    worker: string;
};

/**
 * What somebody wants to happen.
 *
 * Two families in one enum, and the split is by who sends it. The first six
 * are **intentions** the API accepts from a caller. `ExecuteStep` and
 * `RequestInput` are **effects** the decider emits for a reactor or a worker
 * to pick up; they never reach the event log, because ADR_0026 keeps the
 * reasoning in the store and puts only facts about work on the log.
 */
export type WorkflowCommand = {
    command: 'start_execution';
    execution_id: ExecutionId;
    input?: {
        [key: string]: unknown;
    };
    mode: ExecutionMode;
    owner: ExecutionOwner;
    /**
     * Where this run's words live. Recorded rather than looked up, so an
     * append can be checked against what the run was started under years
     * after the deployment's default moved.
     */
    payloads?: PayloadPolicy;
    plan: ExecutionPlan;
    requested_by: string;
} | {
    command: 'retry_step';
    step_id: string;
} | {
    command: 'cancel_execution';
    reason?: string;
} | {
    command: 'pause_execution';
} | {
    command: 'resume_execution';
} | {
    answered_by: string;
    attempt: number;
    command: 'provide_input';
    response: {
        [key: string]: unknown;
    };
    step_id: string;
} | {
    attempt: number;
    command: 'execute_step';
    /**
     * The stable idempotency key: `<execution>/<step>/<attempt>`. What a
     * reactor asks a runtime by before it retries a timeout.
     */
    idempotency_key: string;
    runtime: RuntimeKind;
    step_id: string;
} | {
    attempt: number;
    command: 'request_input';
    step_id: string;
} | {
    attempt: number;
    command: 'timeout_input';
    step_id: string;
};

/**
 * A workflow as the catalog holds it.
 */
export type WorkflowDefinition = {
    declared_at: string;
    edges: Array<WorkflowEdge>;
    executions: number;
    failed: number;
    last_activity_at: string;
    name: string;
    nodes: Array<WorkflowNode>;
    running: number;
    succeeded: number;
    /**
     * Content hash of the declared topology, chosen by the producer.
     *
     * Not interpreted here beyond equality: a changed version replaces the
     * stored shape. It exists so re-declaring on every execution — which is
     * what keeps the catalog alive across retention eviction — costs nothing
     * when the shape has not moved.
     */
    version?: string | null;
    workflow_id: string;
};

/**
 * One declared edge. Direction is `from → to`.
 */
export type WorkflowEdge = {
    from: string;
    label?: string | null;
    to: string;
};

/**
 * What happened.
 *
 * The ones a reactor or a worker reports — `StepStarted`, `StepCompleted`,
 * `StepFailed` — arrive as *inputs* to the decider, because the decider did
 * not know them: something outside performed the effect and came back. Every
 * other variant is an output the decider produced.
 */
export type WorkflowEvent = {
    event: 'execution_requested';
    execution_id: ExecutionId;
    input?: {
        [key: string]: unknown;
    };
    mode: ExecutionMode;
    owner: ExecutionOwner;
    payloads?: PayloadPolicy;
    plan: ExecutionPlan;
    requested_by: string;
} | {
    event: 'execution_started';
} | {
    attempt: number;
    cache_key?: string | null;
    event: 'step_scheduled';
    runtime: RuntimeKind;
    step_id: string;
} | {
    attempt: number;
    event: 'step_retry_scheduled';
    not_before: string;
    step_id: string;
} | {
    attempt: number;
    event: 'step_started';
    step_id: string;
} | {
    attempt: number;
    event: 'step_completed';
    outputs?: Array<ArtifactRef>;
    /**
     * A bounded control value. Rows go in an artifact.
     */
    result?: {
        [key: string]: unknown;
    };
    step_id: string;
} | {
    attempt: number;
    error: StepError;
    event: 'step_failed';
    step_id: string;
} | {
    attempt: number;
    cache_key: string;
    event: 'step_cache_hit';
    outputs?: Array<ArtifactRef>;
    step_id: string;
} | {
    event: 'step_skipped';
    reason: string;
    step_id: string;
} | {
    attempt: number;
    event: 'input_requested';
    request: InputRequest;
    step_id: string;
} | {
    answered_by: string;
    attempt: number;
    event: 'input_provided';
    response: {
        [key: string]: unknown;
    };
    step_id: string;
} | {
    event: 'execution_paused';
} | {
    event: 'execution_resumed';
} | {
    event: 'execution_cancelling';
    reason?: string;
} | {
    event: 'execution_cancelled';
} | {
    event: 'execution_completed';
} | {
    event: 'execution_failed';
    reason: string;
};

export type WorkflowInput = {
    output: string;
    step: string;
};

/**
 * One thing in the stream, whichever kind it is.
 */
export type WorkflowMessage = (WorkflowCommand & {
    kind: 'command';
}) | (WorkflowEvent & {
    kind: 'event';
}) | (HostedMessage & {
    kind: 'hosted';
});

/**
 * One node of a declared graph.
 */
export type WorkflowNode = {
    /**
     * The agent expected to run it, when the graph names one.
     */
    agent?: string | null;
    id: string;
    /**
     * What kind of work it is — `chain`, `retriever`, `agent`, whatever the
     * producer calls it. Free text on purpose: the same reason
     * `data.step_type` is free text, so a new kind is not a backend release.
     */
    kind?: string | null;
    name: string;
};

export type WorkflowPage = {
    next_cursor?: string | null;
    total_known: number;
    workflows: Array<WorkflowDefinition>;
};

/**
 * A workflow's executable definition, saved by content before it is run.
 */
export type WorkflowSpec = {
    name: string;
    steps: Array<WorkflowTask>;
    /**
     * The application's release label; the immutable identity is the revision digest.
     */
    version: string;
};

/**
 * One step of a workflow: work a worker runs, or a gate that waits.
 *
 * Two shapes in one struct rather than a tagged union, because a definition is
 * content-addressed and stored: every revision saved before gates existed has
 * to keep parsing and keep hashing to the same revision. An internally tagged
 * enum has no default tag, so it would have refused all of them. `approval`
 * is what decides which shape this is, and the fields the other shape needs
 * are refused by name when it is set.
 */
export type WorkflowTask = {
    after?: Array<string>;
    approval?: null | ApprovalGate;
    id: string;
    inputs?: Array<WorkflowInput>;
    /**
     * Named row artifacts this step produces.
     */
    outputs?: Array<string>;
    params?: {
        [key: string]: unknown;
    };
    pod?: null | PodRequest;
    queue?: string;
    retry?: RetryPolicy;
    /**
     * A registered function's name and pinned version. Never an import path to
     * execute. Empty on a gate, which runs nothing.
     */
    task_ref?: string;
    /**
     * How long an attempt may take. Absent on a gate: nothing dispatches a
     * wait, so no timer is ever armed and a number here would be a deadline
     * the code does not keep.
     */
    timeout_seconds?: number;
};

